-- RitsuScope: completes the United States wall types (PT01…PT12) in the shared library
-- (generated by scripts/standard-library/us-details.mjs). Run after 20261007_002.
-- 1. Reference documents  2. Catalog products  3. Region, source, page and products on each type
-- 4. Updated material lists (acoustical sealant on PT01/PT12, control joints on every wall).
-- Safe to run more than once. Types stay 'review' until you approve them.

-- 1. Reference documents
insert into public.takeoff_reference_sources (organization_id, name, publisher, country_code, url, notes)
select null, v.name, v.publisher, 'US', v.url, v.notes
from (values
  ('UL Product iQ – Fire Resistance Directory', 'UL Solutions', 'https://productiq.ulprospector.com', 'Fire-rated designs (U400 series for steel-stud walls). Always check the current listing: board brands, layers, screws and joints.'),
  ('GA-600 Fire Resistance and Sound Control Design Manual', 'Gypsum Association', 'https://gypsum.org', 'Generic fire and sound (STC) assemblies for gypsum board systems.'),
  ('The Gypsum Construction Handbook', 'USG', 'https://www.usg.com', 'Installation practice: framing, fastening, joint treatment, control joints, furring and shaft walls.'),
  ('GA-216 Application and Finishing of Gypsum Panel Products', 'Gypsum Association', 'https://gypsum.org', 'Fastener spacing, joint treatment levels and control joint spacing (30 ft max. on walls).')
) as v(name, publisher, url, notes)
where not exists (select 1 from public.takeoff_reference_sources s where s.organization_id is null and s.country_code = 'US' and s.name = v.name);

-- 2. Catalog products (generic, status review)
insert into public.takeoff_materials (organization_id, country_code, name, category, unit, notes, status)
select null, 'US', v.name, v.category, v.unit, v.notes, 'review'
from (values
  ('3-5/8" 25 ga (18 mil) stud', 'stud', 'm', 'Generic product; sold in 10''–16'' lengths (ClarkDietrich, CEMCO, MarinoWARE…). Check limiting heights.'),
  ('3-5/8" 25 ga (18 mil) track', 'track', 'm', 'Generic product; sold in 10'' lengths.'),
  ('5/8" Type X gypsum board 4''×12''', 'board', 'm²', 'Generic product (USG, CertainTeed, Gold Bond, Georgia-Pacific…): for rated walls use a brand listed in the UL design.'),
  ('3" mineral wool batt (sound attenuation)', 'insulation', 'sf', 'Generic product; sold in bags of batts.'),
  ('3-5/8" 20 ga EQ (30 mil) stud', 'stud', 'm', 'Generic product; sold in 10''–16'' lengths (ClarkDietrich, CEMCO, MarinoWARE…). Check limiting heights.'),
  ('3-5/8" 20 ga EQ (30 mil) track', 'track', 'm', 'Generic product; sold in 10'' lengths.'),
  ('6" 20 ga EQ (30 mil) stud', 'stud', 'm', 'Generic product; sold in 10''–16'' lengths (ClarkDietrich, CEMCO, MarinoWARE…). Check limiting heights.'),
  ('6" 20 ga EQ (30 mil) track', 'track', 'm', 'Generic product; sold in 10'' lengths.'),
  ('3-1/2" mineral wool batt', 'insulation', 'sf', 'Generic product; sold in bags of batts.'),
  ('5/8" Type X mold & moisture-resistant gypsum board 4''×12''', 'board', 'm²', 'Generic product (USG, CertainTeed, Gold Bond, Georgia-Pacific…): for rated walls use a brand listed in the UL design.'),
  ('1/2" cement backer board 4''×8''', 'board', 'm²', 'Generic product (USG, CertainTeed, Gold Bond, Georgia-Pacific…): for rated walls use a brand listed in the UL design.'),
  ('5/8" Type X gypsum board 4''×8''', 'board', 'm²', 'Generic product (USG, CertainTeed, Gold Bond, Georgia-Pacific…): for rated walls use a brand listed in the UL design.'),
  ('5/8" abuse-resistant Type X gypsum board 4''×12''', 'board', 'm²', 'Generic product (USG, CertainTeed, Gold Bond, Georgia-Pacific…): for rated walls use a brand listed in the UL design.'),
  ('7/8" 25 ga hat channel (furring stud)', 'stud', 'm', 'Generic product; sold in 10''–16'' lengths (ClarkDietrich, CEMCO, MarinoWARE…). Check limiting heights.'),
  ('7/8" 25 ga J-track', 'track', 'm', 'Generic product; sold in 10'' lengths.'),
  ('2-1/2" 25 ga CH stud', 'stud', 'm', 'Generic product; sold in 10''–16'' lengths (ClarkDietrich, CEMCO, MarinoWARE…). Check limiting heights.'),
  ('2-1/2" 25 ga J-track', 'track', 'm', 'Generic product; sold in 10'' lengths.'),
  ('6" 18 ga (43 mil) stud', 'stud', 'm', 'Generic product; sold in 10''–16'' lengths (ClarkDietrich, CEMCO, MarinoWARE…). Check limiting heights.'),
  ('6" 18 ga (43 mil) track', 'track', 'm', 'Generic product; sold in 10'' lengths.'),
  ('5/8" exterior gypsum sheathing board 4''×8''', 'board', 'm²', 'Generic product (USG, CertainTeed, Gold Bond, Georgia-Pacific…): for rated walls use a brand listed in the UL design.'),
  ('6" fiberglass batt R-19', 'insulation', 'sf', 'Generic product; sold in bags of batts.'),
  ('2-1/2" 25 ga (18 mil) stud', 'stud', 'm', 'Generic product; sold in 10''–16'' lengths (ClarkDietrich, CEMCO, MarinoWARE…). Check limiting heights.'),
  ('2-1/2" 25 ga (18 mil) track', 'track', 'm', 'Generic product; sold in 10'' lengths.')
) as v(name, category, unit, notes)
where not exists (select 1 from public.takeoff_materials m where m.organization_id is null and m.country_code = 'US' and lower(m.name) = lower(v.name));

-- 3. Region, source, page and catalog products on each wall type
update public.takeoff_wall_types set
  region = 'All states (IBC)',
  source_id = (select s.id from public.takeoff_reference_sources s where s.organization_id is null and s.country_code = 'US' and s.name = 'GA-600 Fire Resistance and Sound Control Design Manual' order by s.created_at limit 1),
  source_ref = 'Sound control tables: STC 38–40 for this build-up, perimeter sealed',
  materials = jsonb_strip_nulls(jsonb_build_object('stud', (select m.id from public.takeoff_materials m where m.organization_id is null and m.country_code = 'US' and lower(m.name) = lower('3-5/8" 25 ga (18 mil) stud') order by m.created_at limit 1), 'track', (select m.id from public.takeoff_materials m where m.organization_id is null and m.country_code = 'US' and lower(m.name) = lower('3-5/8" 25 ga (18 mil) track') order by m.created_at limit 1), 'boardA', (select m.id from public.takeoff_materials m where m.organization_id is null and m.country_code = 'US' and lower(m.name) = lower('5/8" Type X gypsum board 4''×12''') order by m.created_at limit 1), 'boardB', (select m.id from public.takeoff_materials m where m.organization_id is null and m.country_code = 'US' and lower(m.name) = lower('5/8" Type X gypsum board 4''×12''') order by m.created_at limit 1))),
  notes = 'Standard interior partition. STC assumes the perimeter sealed with acoustical sealant. Check stud limiting height for the wall height and deflection criteria.',
  updated_at = now()
where organization_id is null and project_id is null and country_code = 'US' and code = 'PT01';
